const LEVELS = {
  read_committed: "READ COMMITTED",
  repeatable_read: "REPEATABLE READ",
  serializable: "SERIALIZABLE",
};

function beginSql(options = {}) {
  let text = "BEGIN";
  if (options.isolation) {
    if (!Object.hasOwn(LEVELS, options.isolation)) throw new TypeError("Unknown isolation level");
    text += ` ISOLATION LEVEL ${LEVELS[options.isolation]}`;
  }
  if (options.readOnly) text += " READ ONLY";
  return text;
}

console.log(beginSql());
console.log(beginSql({ isolation: "serializable" }));
console.log(beginSql({ isolation: "repeatable_read", readOnly: true }));
try {
  beginSql({ isolation: "SERIALIZABLE; DROP TABLE tasks" });
} catch (error) {
  console.log(error.message);
}

