function createTx() {
  const onCommit = [];
  const onRollback = [];
  return {
    afterCommit: (fn) => onCommit.push(fn),
    afterRollback: (fn) => onRollback.push(fn),
    finish(committed) {
      for (const fn of committed ? onCommit : onRollback) fn();
    },
  };
}

const ok = createTx();
ok.afterCommit(() => console.log("email sent"));
ok.afterRollback(() => console.log("log: rolled back"));
